import re,collections
T=open("Transitions.md",encoding='utf-8').read()
secs={}
for m in re.finditer(r'^###+ (\d+\.\d+[a-z]?)\s+(.*)$', T, re.M):
    secs[m.group(1)]=m.group(2).strip()
print("T sections (### n.n): %d  -> %s ... %s"%(len(secs), sorted(secs)[:5], sorted(secs)[-3:]))

vols={'main':'The_Method_1_6-2.md','register':'The_Method_1_6___The_Register-2.md',
      'math':'The_Method_1_6___Mathematical_Compendium-2.md'}
cited=collections.Counter(); where=collections.defaultdict(set)
SRC=re.compile(r"source \*(.*?)\*")
for k,f in vols.items():
    t=open(f,encoding='utf-8').read()
    for loc in re.findall(r"T\s§\s?([0-9][\w.]*)", t):
        cited[loc]+=1; where[loc].add(k)
    for s in SRC.findall(t):
        for loc in re.findall(r"\bT\s(\d[\d.]*[a-z]?)\b", s):
            cited[loc]+=1; where[loc].add(k)
print("\nDISTINCT CITED T LOCATORS: %d | total citations: %d"%(len(cited),sum(cited.values())))
ok=[];bad=[]
for loc,n in sorted(cited.items(), key=lambda x:[int(p) if p.isdigit() else p for p in re.findall(r'\d+|[a-z]',x[0])]):
    (ok if loc in secs else bad).append((loc,n))
print("\nRESOLVE (%d):"%len(ok))
for loc,n in ok: print("   T %-7s x%-2d %-22s %s"%(loc,n,",".join(sorted(where[loc])),secs[loc][:52]))
print("\nDO NOT RESOLVE (%d):"%len(bad))
for loc,n in bad: print("   T %-7s x%-2d %s"%(loc,n,",".join(sorted(where[loc]))))
EOF

